package com.rpb.reservation.workforce.payroll.governance;
import static com.rpb.reservation.workforce.payroll.governance.TemplatePublicationDtos.*;
import com.rpb.reservation.walkin.api.CurrentActor;
import com.rpb.reservation.workforce.application.*;
import com.rpb.reservation.workforce.payroll.PayrollConfigurationRepository;
import com.rpb.reservation.workforce.payroll.PayrollDtos.SalaryTemplate;
import com.rpb.reservation.workforce.domain.WorkforceException;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
@Service @Transactional(readOnly=true)
public class TemplateAdoptionService {
 private final WorkforceAccess access;private final TemplatePublicationRepository repository;private final PayrollConfigurationRepository configs;private final WorkforceAudit audit;private final TemplatePublicationScope scope;
 public TemplateAdoptionService(WorkforceAccess access,TemplatePublicationRepository repository,PayrollConfigurationRepository configs,WorkforceAudit audit){this.access=access;this.repository=repository;this.configs=configs;this.audit=audit;this.scope=new TemplatePublicationScope(access,repository);}
 public List<LibraryEntry> library(CurrentActor actor,UUID store){var shop=scope.managed(actor,store);var latest=new LinkedHashMap<UUID,Release>();for(var r:repository.releases(actor.tenantId()))if(scope.visible(r,shop))latest.put(r.masterId(),r);return latest.values().stream().map(r->{var a=current(actor,shop,r.masterId());return new LibraryEntry(r.masterId(),r.name(),r.version(),a,a==null?"available":a.releaseVersion()<r.version()?"updateAvailable":"enabled",repository.scheduled(actor.tenantId(),store,r.masterId()));}).toList();}
 public Preview preview(CurrentActor actor,UUID store,UUID id,long version){var shop=scope.managed(actor,store);var r=visible(actor,shop,id,version);var a=current(actor,shop,id);boolean update=repository.releases(actor.tenantId()).stream().anyMatch(next->next.masterId().equals(id)&&next.version()>(a==null?version:a.releaseVersion())&&scope.visible(next,shop));return new Preview(r,a,update,repository.scheduled(actor.tenantId(),store,id));}
 @Transactional public Adoption enable(CurrentActor actor,UUID store,UUID id,Enable c){var shop=scope.managed(actor,store);if(c==null||c.commandId()==null||c.releaseVersion()==null||c.releaseVersion()<1||c.expectedAdoptionVersion()==null||c.expectedAdoptionVersion()<0)throw WorkforceException.invalid();access.sourceWrite(actor);repository.lock("command:"+c.commandId());repository.lock("adoption:"+actor.tenantId()+":"+store+":"+id);shop=scope.managed(actor,store);var r=visible(actor,shop,id,c.releaseVersion());var payload=Map.of("masterId",id,"releaseVersion",c.releaseVersion(),"expectedAdoptionVersion",c.expectedAdoptionVersion());var replay=repository.replay(actor.tenantId(),actor.actorId(),store,c.commandId(),"enable",payload,Adoption.class);if(replay.isPresent()){if(!replay.get().companyId().equals(shop.companyId()))throw WorkforceException.forbidden();return replay.get();}if(!repository.scheduled(actor.tenantId(),store,id).isEmpty())throw WorkforceException.conflict();var old=repository.current(actor.tenantId(),store,id).orElse(null);long version=repository.latest(actor.tenantId(),store,id).map(Adoption::storeVersion).orElse(0L);long expected=old==null||!old.companyId().equals(shop.companyId())?0:old.storeVersion();if(expected!=c.expectedAdoptionVersion())throw WorkforceException.conflict();if(old!=null&&old.companyId().equals(shop.companyId())&&old.releaseVersion()!=r.version()){var base=repository.release(actor.tenantId(),id,old.releaseVersion()).orElseThrow(WorkforceException::missing);if(!base.rule().equals(old.rule()))throw new WorkforceException("WORKFORCE_PAYROLL_TEMPLATE_UPGRADE_REQUIRED",409);}Adoption next;if(old!=null&&old.companyId().equals(shop.companyId())&&old.releaseVersion()==r.version())next=old;else{next=new Adoption(UUID.randomUUID(),id,r.version(),shop.companyId(),store,version+1,UUID.randomUUID(),r.name(),r.rule(),actor.actorId(),repository.now());var materialized=new SalaryTemplate(next.materializedTemplateId(),shop.companyId(),r.name(),r.rule(),true,1,new com.rpb.reservation.workforce.payroll.PayrollDtos.TemplateGovernanceSource(next.id(),store,id,r.version()));configs.effective().adoption(actor.tenantId(),materialized,next);configs.saveTemplate(actor.tenantId(),materialized);repository.adopt(actor.tenantId(),next);audit.changed(actor,store,"pay-template.enable",next.id(),old,next);}repository.command(actor.tenantId(),actor.actorId(),store,c.commandId(),"enable",payload,next);return next;}
 private Release visible(CurrentActor actor,TemplatePublicationRepository.Store shop,UUID id,long version){var r=repository.release(actor.tenantId(),id,version).orElseThrow(WorkforceException::missing);if(!scope.visible(r,shop))throw WorkforceException.forbidden();return r;}
 private Adoption current(CurrentActor actor,TemplatePublicationRepository.Store shop,UUID id){var a=repository.current(actor.tenantId(),shop.id(),id).orElse(null);if(a==null||!a.companyId().equals(shop.companyId()))return null;return repository.release(actor.tenantId(),id,a.releaseVersion()).filter(r->scope.visible(r,shop)).isPresent()?a:null;}
}
